INSERT OR IGNORE INTO `tournament_match_summaries` (`id`,`event_id`,`round`,`best_of`,`leader_one_code`,`archetype_one`,`player_one_name`,`leader_two_code`,`archetype_two`,`player_two_name`,`score_one`,`score_two`,`winner_leader_code`,`winner_side`,`series_complete`,`score_complete`,`summary`,`source_name`,`source_url`,`evidence_status`) VALUES
('london-offline-regional-2026-grand-final-mihawk-enel','london-offline-regional-2026','Grand Final',3,'OP14-020','Green Dracule Mihawk','Davide','OP15-058','Purple Enel','Sebastian (Zixo)',2,1,'OP14-020',1,1,1,'Green Dracule Mihawk wins the London Regional final 2-1. Game 1: Both players curve out, but Enel hits a low-impact one-cost card early instead of a high-impact six-cost target later. Mihawk builds pressure with Yasopp and six-cost Law. Yasopp rests key Enel characters such as Holly, while Law rebuilds Mihawk’s board and strips cards from Enel’s hand. Enel spends too many resources defending, cannot turn his setup into lethal, and Davide takes the game. Game 2: Both starts are clunky. Mihawk’s Pudding and Otama miss searches, and Enel removes Otama before they can set up safe Law plays. Enel sees mostly events and uses Satori, Mamagan, Lightning Dragon, Gamma Knife, and Holly to control the board. Power reduction followed by Gamma Knife clears Oden and Law, while Lightning Dragon buys tempo. A double Gamma Knife turn followed by a buffed attack clears both Odens and removes more cards from Mihawk’s hand. Davide is left low on life with multiple ten-cost Shanks stranded and too few blockers or counters. Enel keeps the board small, chips away at life, and wins the game. Game 3: Enel opens with mostly events and finds few characters, while Mihawk curves Otama, Kin’emon, Oden, and additional Samurai, then uses Coffin Boat to keep cards flowing. Enel uses Lightning Dragon, Mamagan, power-reduction events, six-cost Enel, Holly, and M to stay alive and look for a double-attack line. Mihawk’s six-cost Law, five-cost bodies, and Oden refill and protect the board. Ten-cost Shanks removes both Senor Pinks, and four-cost Riplaw strips more counter from Enel’s hand. Davide keeps a dominant board and closes the game, taking the final 2-1.','User-provided match summary','https://tickets.organizedplay.events/Event/Index/175','SUMMARY_ONLY');
